def seed_support_types(apps, schema_editor):
    Type = apps.get_model('portals', 'SupportRequestType')
    Request = apps.get_model('portals', 'PortalRequest')
    Counter = apps.get_model('core', 'SequenceCounter')
    support, _ = Type.objects.get_or_create(
        code='SUPPORT',
        defaults={'name': 'Support', 'description': 'A general question for the centre.', 'response_hours': 24, 'sort_order': 1},
    )
    correction, _ = Type.objects.get_or_create(
        code='CORRECTION',
        defaults={'name': 'Ask for a correction', 'description': 'Ask the centre to review a detail on the record.', 'response_hours': 48, 'sort_order': 2},
    )
    count = 0
    for row in Request.objects.all().order_by('created_at'):
        count += 1
        row.reference = f'SUP-{count:06d}'
        row.request_type = correction if row.kind == 'CORRECTION' else support
        if not row.kind:
            row.kind = row.request_type.code
        row.save(update_fields=['reference', 'request_type', 'kind'])
    if count:
        Counter.objects.update_or_create(key='support-request', defaults={'value': count})


